p echo (float)($h['agreed_sponsorship_amount']??0); ?>" data-agreed-service-fee="<?php echo (float)($h['agreed_service_fee_amount']??0); ?>" title="تعديل وإعادة إرسال"><i class="fas fa-pen"></i></button><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div></div><?php endif; ?>
