<div class="modal fade" id="editModal" tabindex="-1"><div class="modal-dialog"><form method="post" enctype="multipart/form-data"><?php echo csrf_field(); ?><input type="hidden" name="edit_record" value="1"><input type="hidden" name="edit_src" id="edit-src"><input type="hidden" name="edit_id" id="edit-id"><div class="modal-content"><div class="modal-header bg-warning"><h5 class="modal-title"><i class="fas fa-pen me-2"></i>تعديل وإعادة إرسال الدفعة</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="alert alert-info small mb-3"><i class="fas fa-shield-halved me-1"></i>هذه الدفعة أُعيدت من المدير المالي. بعد التعديل ستعود تلقائياً إلى طابور المراجعة، ولن يتم إنشاء قيد محاسبي حتى الاعتماد.</div><div class="row g-3"><div class="col-md-6"><label class="form-label">سداد عن شهر</label><select name="edit_month" id="edit-month" class="form-select"><?php foreach($monthOptions as $m): ?><option value="<?php echo $m; ?>"><?php echo $m; ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">غرض الدفعة</label><select name="edit_purpose" id="edit-purpose" class="form-select"><?php foreach($purposeLabels as $pk=>$pl2): ?><option value="<?php echo $pk; ?>"><?php echo $pl2; ?></option><?php endforeach; ?></select></div><div class="col-12"><label class="form-label">توضيح الغرض</label><input type="text" name="edit_note" id="edit-note" class="form-control"></div><div class="col-md-6" id="edit-amount-wrap"><label class="form-label">المبلغ</label><input type="number" step="0.01" name="edit_amount" id="edit-amount" class="form-control" required></div><div class="col-12" id="edit-component-fields" style="display:none"><div class="row g-2 border rounded p-2"><div class="col-md-3"><label class="form-label">الكفالة المتفق عليها</label><input type="text" id="edit-agreed-sponsorship" class="form-control" readonly></div><div class="col-md-3"><label class="form-label">الكفالة المستلمة فعلياً</label><input type="number" min="0" step="0.01" name="edit_actual_sponsorship" id="edit-actual-sponsorship" class="form-control"></div><div class="col-md-3"><label class="form-label">رسوم الخدمة المتفق عليها</label><input type="text" id="edit-agreed-service-fee" class="form-control" readonly></div><div class="col-md-3"><label class="form-label">رسوم الخدمة المستلمة فعلياً</label><input type="number" min="0" step="0.01" name="edit_actual_service_fee" id="edit-actual-service-fee" class="form-control"></div><div class="col-12 small text-muted">تبقى الاتفاقية وقيمها المرجعية ثابتة؛ التعديل مسموح لمبالغ الاستلام الفعلية فقط.</div></div></div><div class="col-12"><label class="form-label">استبدال إيصال البند (اختياري)</label><input type="file" name="edit_receipt_file" class="form-control" accept="image/jpeg,image/png,application/pdf"></div><div class="col-12"><label class="form-label">استبدال الإيصال الموحّد (اختياري)</label><input type="file" name="edit_unified_file" class="form-control" accept="image/jpeg,image/png,application/pdf"></div></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">إلغاء</button><button type="submit" class="btn btn-warning" onclick="return confirm('حفظ التعديلات وإعادة إرسال الدفعة للمراجعة المالية؟')">حفظ وإعادة إرسال</button></div></div></form></div></div>
<script>
const MONTHS=<?php echo json_encode($monthOptions); ?>;const CUR=<?php echo json_encode($CURRENT_MONTH); ?>;const PURPOSES=<?php echo json_encode($purposeLabels,JSON_UNESCAPED_UNICODE); ?>;const AGREEMENTS=<?php echo json_encode($agreementOptions,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT); ?>;function monthSelectHtml(selected){let html='<select name="pay_month[]" class="form-select form-select-sm line-month">';MONTHS.forEach(m=>{html+='<option value="'+m+'"'+(m===selected?' selected':'')+'>'+m+'</option>';});return html+'</select>';}function purposeSelectHtml(selected){let html='<select name="pay_purpose[]" class="form-select form-select-sm line-purpose">';for(const[v,l]of Object.entries(PURPOSES))html+='<option value="'+v+'"'+(v===selected?' selected':'')+'>'+l+'</option>';return html+'</select>';}function showAgreementSummary(line){const sponsorshipField=document.getElementById('selectedAgreedSponsorship');const serviceFeeField=document.getElementById('selectedAgreedServiceFee');const monthLabel=document.getElementById('agreementSummaryMonth');if(!line){sponsorshipField.value='';serviceFeeField.value='';monthLabel.textContent='لا توجد تفاصيل شهرية محددة.';return;}const monthly=line.querySelector('.line-purpose').value==='monthly_sponsorship';const month=line.querySelector('.line-month').value;const agreement=monthly?AGREEMENTS[month]:null;sponsorshipField.value=agreement?Number(agreement.sponsorship).toFixed(2):(monthly?'لا توجد اتفاقية':'—');serviceFeeField.value=agreement?Number(agreement.service_fee).toFixed(2):(monthly?'لا توجد اتفاقية':'—');monthLabel.textContent=monthly?'القيم المعروضة تخص شهر '+month+'. وهي مبالغ متفق عليها مرجعية وليست إثباتاً للتحصيل الفعلي.':'السطر المحدد ليس تحصيل كفالة شهرية.';}function updateLine(line,resetActuals=false){const monthly=line.querySelector('.line-purpose').value==='monthly_sponsorship';const componentCells=line.querySelectorAll('.line-components');const amount=line.querySelector('.line-amount');const actualS=line.querySelector('.actual-sponsorship');const actualF=line.querySelector('.actual-service-fee');componentCells.forEach(cell=>cell.style.display=monthly?'':'none');actualS.disabled=!monthly;actualF.disabled=!monthly;amount.readOnly=monthly;if(monthly){const month=line.querySelector('.line-month').value;const a=AGREEMENTS[month];line.querySelector('.agreement-status').textContent=a?'اتفاقية الشهر مسجلة.':'لا توجد اتفاقية مسجلة لهذا الشهر. لا يمكن إرسال تحصيل الكفالة قبل تسجيلها.';if(resetActuals){actualS.value='';actualF.value='';}const evidence=line.nextElementSibling;const purposeNote=evidence?evidence.querySelector('.line-purpose-note-wrap'):null;if(purposeNote)purposeNote.style.display='none';}else{line.querySelector('.agreement-status').textContent='';const evidence=line.nextElementSibling;const purposeNote=evidence?evidence.querySelector('.line-purpose-note-wrap'):null;if(purposeNote)purposeNote.style.display=line.querySelector('.line-purpose').value==='other'?'':'none';}recalcTotal();recalcDonationTotal();}function addLine(){const wrap=document.getElementById('linesWrap');const div=document.createElement('tr');div.className='pay-line';div.innerHTML='<td>'+monthSelectHtml(CUR)+'</td><td>'+purposeSelectHtml('monthly_sponsorship')+'</td><td class="line-components"><input type="number" min="0" step="0.01" name="pay_sponsorship_received[]" class="form-control form-control-sm actual-sponsorship text-end" dir="ltr"></td><td class="line-components"><input type="number" min="0" step="0.01" name="pay_service_fee_received[]" class="form-control form-control-sm actual-service-fee text-end" dir="ltr"></td><td><input type="number" step="0.01" min="0" name="pay_amount[]" class="form-control form-control-sm line-amount" dir="ltr" readonly></td><td><input type="file" name="pay_receipt_file[]" class="form-control form-control-sm" accept="image/jpeg,image/png,application/pdf"></td><td class="text-center"><button type="button" class="btn btn-sm btn-outline-danger" onclick="removeLine(this)" title="حذف السطر"><i class="fas fa-trash"></i></button><div class="small text-muted agreement-status line-components mt-1"></div></td>';const evidence=document.createElement('tr');evidence.className='pay-evidence-row';evidence.innerHTML='<td colspan="7"><div class="pay-evidence-panel"><div class="small fw-bold text-primary mb-2">تفاصيل الدفع والإثبات لهذا السطر</div><div class="row g-2 align-items-end"><div class="col-6 col-lg-2"><label class="form-label">تاريخ التحصيل *</label><input type="date" name="pay_date[]" class="form-control form-control-sm" required value="'+<?php echo json_encode(date('Y-m-d')); ?>+'"></div><div class="col-6 col-lg-2"><label class="form-label">طريقة الدفع *</label><select name="pay_method[]" class="form-select form-select-sm" required><option value="cash" selected>نقدي</option><option value="bank_transfer">تحويل بنكي</option><option value="mobile">محفظة إلكترونية</option><option value="credit_card">بطاقة</option><option value="other">أخرى</option></select></div><div class="col-6 col-lg-2"><label class="form-label">رقم الإيصال</label><input type="text" name="pay_receipt[]" class="form-control form-control-sm" dir="ltr" maxlength="50"></div><div class="col-6 col-lg-2"><label class="form-label">مرجع إضافي</label><input type="text" name="pay_reference[]" class="form-control form-control-sm" dir="ltr" maxlength="100"></div><div class="col-6 col-lg-2"><label class="form-label">ملاحظات / البيان</label><input type="text" name="pay_description[]" class="form-control form-control-sm" maxlength="255"></div><div class="col-6 col-lg-2 line-purpose-note-wrap" style="display:none"><label class="form-label">توضيح الغرض الآخر</label><input type="text" name="pay_note[]" class="form-control form-control-sm" maxlength="255"></div></div></div></td>';wrap.appendChild(div);wrap.appendChild(evidence);updateLine(div,true);showAgreementSummary(div);}function removeLine(btn){const lines=document.querySelectorAll('.pay-line');if(lines.length>1){const line=btn.closest('.pay-line');const evidence=line.nextElementSibling;if(evidence&&evidence.classList.contains('pay-evidence-row'))evidence.remove();line.remove();}else{const l=lines[0];l.querySelectorAll('select')[0].value=CUR;l.querySelectorAll('select')[1].value='monthly_sponsorship';l.querySelector('.actual-sponsorship').value='';l.querySelector('.actual-service-fee').value='';l.querySelector('.line-amount').value='';const evidence=l.nextElementSibling;if(evidence&&evidence.classList.contains('pay-evidence-row'))evidence.querySelectorAll('input,select').forEach(field=>{if(field.name==='pay_date[]')field.value=<?php echo json_encode(date('Y-m-d')); ?>;else if(field.name==='pay_method[]')field.value='cash';else field.value='';});updateLine(l,true);}showAgreementSummary(document.querySelector('.pay-line'));recalcTotal();}function recalcTotal(){let t=0;document.querySelectorAll('.pay-line').forEach(line=>{const monthly=line.querySelector('.line-purpose').value==='monthly_sponsorship';const amount=line.querySelector('.line-amount');if(monthly){const a=parseFloat(line.querySelector('.actual-sponsorship').value)||0;const b=parseFloat(line.querySelector('.actual-service-fee').value)||0;amount.value=(a+b).toFixed(2);}t+=parseFloat(amount.value)||0;});const el=document.getElementById('linesTotal');if(el)el.textContent=t.toLocaleString('en-US');}function toggleFields(){toggleDonationFields();}function toggleDonationFields(row){const rows=row?[row]:Array.from(document.querySelectorAll('.donation-line'));rows.forEach(line=>{const type=line.querySelector('.donation-type').value;const project=line.querySelector('.donation-project');const source=line.querySelector('.donation-source');project.disabled=type!=='project_donation';project.required=type==='project_donation';source.disabled=type!=='other';source.required=type==='other';});}function addDonationLine(){const wrap=document.getElementById('donationLinesWrap');const tr=document.createElement('tr');tr.className='donation-line';tr.innerHTML='<td><select name="donation_type[]" class="form-select donation-type" required><option value="general_donation">تبرع عام</option><option value="project_donation">تبرع لحملة/مشروع</option><option value="other">مصدر آخر</option></select></td><td><input type="number" step="0.01" min="0.01" name="donation_amount[]" class="form-control donation-amount" required></td><td><select name="donation_project_id[]" class="form-select donation-project"><option value="">— اختر —</option><?php foreach($projects as $p): ?><option value="<?php echo (int)$p['id']; ?>"><?php echo e($p['name']); ?></option><?php endforeach; ?></select></td><td><input type="text" name="donation_other_source_note[]" class="form-control donation-source" maxlength="255" placeholder="حدد الجهة أو المصدر"></td><td class="text-center"><button type="button" class="btn btn-sm btn-outline-danger" onclick="removeDonationLine(this)"><i class="fas fa-trash"></i></button></td>';const evidence=document.createElement('tr');evidence.className='donation-evidence-row';evidence.innerHTML='<td colspan="5"><div class="pay-evidence-panel"><div class="small fw-bold text-primary mb-2">بيانات الدفع والإثبات لهذا التبرع</div><div class="row g-2 align-items-end"><div class="col-6 col-lg-2"><label class="form-label">التاريخ *</label><input type="date" name="donation_date[]" class="form-control form-control-sm" required value="<?php echo date('Y-m-d'); ?>"></div><div class="col-6 col-lg-2"><label class="form-label">طريقة الدفع *</label><select name="donation_method[]" class="form-select form-select-sm" required><option value="cash">نقدي</option><option value="bank_transfer">تحويل بنكي</option><option value="mobile">محفظة إلكترونية</option><option value="credit_card">بطاقة</option><option value="other">أخرى</option></select></div><div class="col-6 col-lg-2"><label class="form-label">رقم الإيصال</label><input type="text" name="donation_receipt[]" class="form-control form-control-sm" maxlength="50" dir="ltr"></div><div class="col-6 col-lg-2"><label class="form-label">مرجع إضافي</label><input type="text" name="donation_reference[]" class="form-control form-control-sm" maxlength="100" dir="ltr"></div><div class="col-6 col-lg-2"><label class="form-label">ملاحظات / البيان</label><input type="text" name="donation_description[]" class="form-control form-control-sm" maxlength="255"></div><div class="col-6 col-lg-2"><label class="form-label">إيصال التبرع</label><input type="file" name="donation_receipt_file[]" class="form-control form-control-sm" accept="image/jpeg,image/png,application/pdf"></div></div></div></td>';wrap.appendChild(tr);wrap.appendChild(evidence);toggleDonationFields(tr);recalcDonationTotal();}function removeDonationLine(button){const rows=document.querySelectorAll('.donation-line');const row=button.closest('.donation-line');const evidence=row.nextElementSibling;if(rows.length>1){if(evidence&&evidence.classList.contains('donation-evidence-row'))evidence.remove();row.remove();}else{row.querySelector('.donation-type').value='general_donation';row.querySelector('.donation-amount').value='';row.querySelector('.donation-project').value='';row.querySelector('.donation-source').value='';if(evidence)evidence.querySelectorAll('input,select').forEach(field=>{if(field.name==='donation_date[]')field.value='<?php echo date('Y-m-d'); ?>';else if(field.name==='donation_method[]')field.value='cash';else field.value='';});toggleDonationFields(row);}recalcDonationTotal();}function recalcDonationTotal(){let total=0;document.querySelectorAll('.donation-amount').forEach(field=>total+=parseFloat(field.value)||0);const target=document.getElementById('donationLinesTotal');if(target)target.textContent=total.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});}document.addEventListener('input',e=>{if(e.target.classList.contains('line-amount')||e.target.classList.contains('actual-sponsorship')||e.target.classList.contains('actual-service-fee'))recalcTotal();if(e.target.classList.contains('donation-amount'))recalcDonationTotal();});document.addEventListener('focusin',e=>{const line=e.target.closest('.pay-line');if(line)showAgreementSummary(line);});document.addEventListener('change',e=>{if(e.target.classList.contains('donation-type'))toggleDonationFields(e.target.closest('.donation-line'));if(e.target.classList.contains('line-purpose')){const line=e.target.closest('.pay-line');updateLine(line,false);showAgreementSummary(line);}if(e.target.classList.contains('line-month')){const line=e.target.closest('.pay-line');updateLine(line,true);showAgreementSummary(line);}if(e.target.name==='sponsorship_id'){const option=e.target.selectedOptions[0];if(option&&e.target.value){const params=new URLSearchParams(window.location.search);params.set('sponsorship_id',e.target.value);params.set('sponsor_id',option.dataset.sponsorId||'');window.location.search=params.toString();}}});document.addEventListener('DOMContentLoaded',function(){var detModal=document.getElementById('detailsModal');if(detModal){detModal.addEventListener('show.bs.modal',function(event){var btn=event.relatedTarget;document.getElementById('det-period').textContent=btn.getAttribute('data-period');document.getElementById('det-type').textContent=btn.getAttribute('data-type');document.getElementById('det-note').textContent=btn.getAttribute('data-note')||'—';document.getElementById('det-amount').textContent=btn.getAttribute('data-amount')+' ج.س';document.getElementById('det-status').textContent=btn.getAttribute('data-status');});}var editModal=document.getElementById('editModal');if(editModal){editModal.addEventListener('show.bs.modal',function(event){var btn=event.relatedTarget;document.getElementById('edit-src').value=btn.getAttribute('data-src');document.getElementById('edit-id').value=btn.getAttribute('data-id');document.getElementById('edit-month').value=btn.getAttribute('data-period');document.getElementById('edit-purpose').value=btn.getAttribute('data-purpose');document.getElementById('edit-note').value=btn.getAttribute('data-note');document.getElementById('edit-amount').value=btn.getAttribute('data-amount');var isComponent=btn.getAttribute('data-component-model')==='monthly_agreement';document.getElementById('edit-component-fields').style.display=isComponent?'':'none';document.getElementById('edit-amount-wrap').style.display=isComponent?'none':'';document.getElementById('edit-amount').required=!isComponent;document.getElementById('edit-actual-sponsorship').value=btn.getAttribute('data-actual-sponsorship')||'';document.getElementById('edit-actual-service-fee').value=btn.getAttribute('data-actual-service-fee')||'';document.getElementById('edit-agreed-sponsorship').value=btn.getAttribute('data-agreed-sponsorship')||'';document.getElementById('edit-agreed-service-fee').value=btn.getAttribute('data-agreed-service-fee')||'';document.getElementById('edit-month').disabled=isComponent;document.getElementById('edit-purpose').disabled=isComponent;});}});toggleFields();const initialLines=document.querySelectorAll('.pay-line');initialLines.forEach(line=>updateLine(line,false));showAgreementSummary(initialLines[0]||null);recalcTotal();
</script>

